edits.replacement:
.ui-key.pill{ border-radius:12px; padding:0 9px; }
/* vNN.xx, UI REDESIGN ui5q1x (his #50, from the visual QA of the Mainframe RACKS and REWARDS tabs): one left edge. Both panes were
   a centred 1080px column under the title and tabs on the left edge, the two-layouts look Settings had (ui5q1g). They start on the
   left edge under the tabs and run 1320px, as Settings does. */
#root #opane_mf, #root #opane_rew{ max-width:1320px; margin:0; }

check:
{v:'VER',what:'his #50 (UI redesign ui5q1x, from the visual QA of the Mainframe RACKS and REWARDS tabs): the RACKS and REWARDS panes start on the left edge of the tabs, not centred',
 run:function(){
   var bad=[], ids=['opane_mf','opane_rew'], i, p, s;
   for(i=0;i<ids.length;i++){
     p=document.getElementById(ids[i]); if(!p) continue;
     s=getComputedStyle(p);
     if(s.marginLeft==='auto'||(parseFloat(s.marginLeft)>2&&s.display!=='none')) bad.push(ids[i]+' is centred (margin-left '+s.marginLeft+')');
     if(!(parseFloat(s.maxWidth)>=1300)) bad.push(ids[i]+' is held to '+s.maxWidth);
   }
   return bad.length?bad.join('; '):null; }},
